declare(strict_types=1);require dirname(__DIR__).'/app/models.php';require dirname(__DIR__).'/app/learning.php';require dirname(__DIR__).'/app/explore.php';$base=rtrim($argv[1]??'http://127.0.0.1:8080','/');$passed=0;$failed=0;
function get_response($path,$method='GET',$body=null,$type='application/json'){global $base;$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>'Content-Type: '.$type."\r\n",'content'=>$body??'','ignore_errors'=>true,'follow_location'=>0,'timeout'=>10]]);$text=@file_get_contents($base.$path,false,$ctx);if($text===false)throw new RuntimeException('HTTP connection failed');$headers=$http_response_header??[];preg_match('/\s(\d{3})\s/',$headers[0]??'',$m);return [(int)($m[1]??0),$text,implode("\n",$headers)];}
function check($ok,$m='assertion'){if(!$ok)throw new RuntimeException($m);}
function test($n,$fn){global $passed,$failed;try{$fn();echo "PASS $n\n";$passed++;}catch(Throwable $e){echo "FAIL $n: {$e->getMessage()}\n";$failed++;}}
$paths=array_merge(['/','/concepts/','/labs/','/methods/','/agents/','/about/'],learning_routes(),scene_routes());foreach(topics() as $t)$paths[]='/concepts/'.$t['slug'].'/';foreach(labs() as $l)$paths[]='/labs/'.$l['id'].'/';
foreach($paths as $path)test('route '.$path,function()use($path){[$s,$h,$hdr]=get_response($path);check($s===200,'status '.$s);check(substr_count($h,'<h1>')===1);check(str_contains($h,'rel="canonical" href="https://beyondspacetime.org'.$path.'"'));check(str_contains($hdr,'Content-Security-Policy:'));preg_match('~<script type="application/ld\+json">(.*?)</script>~s',$h,$m);check(isset($m[1]));json_decode($m[1],true,512,JSON_THROW_ON_ERROR);});
test('sitemap unique complete',function()use($paths){[$s,$h]=get_response('/sitemap.xml');check($s===200);preg_match_all('~<loc>(.*?)</loc>~',$h,$m);check(count($m[1])===count($paths));check(count(array_unique($m[1]))===count($paths));foreach($paths as $path)check(in_array('https://beyondspacetime.org'.$path,$m[1],true));});
test('robots and machine guide',function(){[$s,$r]=get_response('/robots.txt');check($s===200&&str_contains($r,'Sitemap: https://beyondspacetime.org/sitemap.xml'));[$s,$l]=get_response('/llms.txt');check($s===200&&str_contains($l,'https://arcsecs.com/read-book/'));});
foreach(['/app/models.php'=>403,'/app/topics.json'=>403,'/tests/models-test.php'=>403,'/unknown/'=>404,'/api/unknown/'=>404,'/api/ag-ui/'=>405,'/api/v1/experiment/'=>405,'/concepts'=>301] as $path=>$expected)test('status '.$path,function()use($path,$expected){[$s]=get_response($path);check($s===$expected,"$s != $expected");});
foreach([['experiment'=>'x'],['experiment'=>'bubble','parameters'=>['radius'=>-1]],['experiment'=>'population','parameters'=>['seed'=>1.3]],['experiment'=>'outflow','parameters'=>['gap'=>.4,'redshift'=>3]],['experiment'=>'bubble','parameters'=>['radius'=>[1]]]] as $i=>$bad)test('invalid JSON model '.$i,function()use($bad){[$s]=get_response('/api/v1/experiment/','POST',json_encode($bad));check($s===400);});
foreach(['{',str_repeat('x',32769)] as $i=>$bad)test('bad request body '.$i,function()use($bad){[$s]=get_response('/api/v1/experiment/','POST',$bad);check($s===400);});
test('wrong content type',function(){[$s]=get_response('/api/v1/experiment/','POST','{}','text/plain');check($s===400);});
foreach(labs() as $id=>$lab)test('API matches PHP '.$id,function()use($id){[$s,$b]=get_response('/api/v1/experiment/','POST',json_encode(['experiment'=>$id,'parameters'=>(object)[]]));check($s===200);check(json_decode($b,true)==calc($id));});
foreach([['topic'=>'bubble-universes'],['experiment'=>'bubble','parameters'=>['radius'=>1.6]]] as $state)test('AG-UI '.array_key_first($state),function()use($state){[$s,$b,$headers]=get_response('/api/ag-ui/','POST',json_encode(['threadId'=>'t','runId'=>'r','messages'=>[],'state'=>$state]));check($s===200&&str_contains($headers,'text/event-stream'));preg_match_all('/^data: (.*)$/m',$b,$m);$events=array_map(fn($e)=>json_decode($e,true,512,JSON_THROW_ON_ERROR),$m[1]);check(array_column($events,'type')===['RUN_STARTED','TEXT_MESSAGE_START','TEXT_MESSAGE_CONTENT','TEXT_MESSAGE_END','STATE_SNAPSHOT','RUN_FINISHED']);check($events[0]['runId']===$events[5]['runId']);check($events[1]['messageId']===$events[2]['messageId']&&$events[1]['messageId']===$events[3]['messageId']);});
test('no JavaScript form calculation',function(){[$s,$h]=get_response('/labs/bubble/','POST','p%5Bradius%5D=1.6','application/x-www-form-urlencoded');check($s===200&&str_contains($h,'Balanced'));});
test('favicon ICO signature',function(){[$s,$b]=get_response('/favicon.ico');check($s===200&&substr($b,0,4)==="\x00\x00\x01\x00");});
test('compass PNG signature',function(){[$s,$b]=get_response('/assets/compass.png');check($s===200&&substr($b,0,8)==="\x89PNG\r\n\x1a\n");});
test('comparison API and delta',function(){[$s,$b]=get_response('/api/v1/compare/','POST',json_encode(['experiment'=>'parallax','left'=>['baseline'=>1],'right'=>['baseline'=>2]]));check($s===200);$r=json_decode($b,true);check($r['differences'][0]['delta']===10.0||$r['differences'][0]['delta']===10);});
