test('comparison no JS form',function(){[$s,$h]=get_response('/compare/','POST',http_build_query(['experiment'=>'parallax','left'=>['baseline'=>1],'right'=>['baseline'=>2]]),'application/x-www-form-urlencoded');check($s===200&&str_contains($h,'Calculated differences')&&str_contains($h,'Geometric distance'));});
