test('featured video is local until activation',function(){[$s,$h,$hdr]=get_response('/');check($s===200&&str_contains($h,'id="featured-video-play"')&&str_contains($h,'https://youtu.be/b5560LP8Wx0'));check(!str_contains($h,'<iframe'));check(str_contains($hdr,'frame-src https://www.youtube-nocookie.com'));[$s,$js]=get_response('/assets/site.js');check($s===200&&str_contains($js,'https://www.youtube-nocookie.com/embed/b5560LP8Wx0?autoplay=1'));});
